// Controller event regression; this does not replace a normal browser test.
import test from 'node:test';import assert from 'node:assert/strict';
import {mountDesktopWorkflowScreen} from './desktopWorkflowScreen.mjs';
import {desktopSeriesDraftItems} from './desktopSeriesDraft.mjs';
import {createDesktopWorkflowClient} from './desktopWorkflowClient.mjs';

test('excess carton totals across boxes reject before UUID, journal or POST and allow correcting the same form',async()=>{
 for(const split of [false,true]){
  const node=root(),store=new Map([['melisa.desktop.workflow.last.v1.8','16']]),sent=[];let ids=0;
  const storage={getItem:k=>store.get(k)??null,setItem:(k,v)=>store.set(k,v),removeItem:k=>store.delete(k)};
  const record={invoiceId:'16',documentNo:'DS-K06',customerName:'Deneme',customerId:'2',documentDate:'2026-11-07',workflowState:'PREPARING',version:'0x0000000000000016',totalExact4:'24.0000',items:[{itemId:'27',productId:'10',stockCode:'FX2',name:'Bir',quantityExact3:'1.000',unitPriceExact4:'12.0000',lineTotalExact4:'12.0000'},{itemId:'28',productId:'11',stockCode:'FX3',name:'İki',quantityExact3:'1.000',unitPriceExact4:'12.0000',lineTotalExact4:'12.0000'}],cartonItems:[]};
  const client=createDesktopWorkflowClient({actorId:'8',storage,locks:{request:async(_key,_options,work)=>work({})},newId:()=>{ids++;return '822c4dcc-3405-43e7-92a4-bd0d9f84b801';},submit:async(kind,body)=>{sent.push({kind,body});return {state:'UNKNOWN',requestId:body.requestId};}});
  const screen=mountDesktopWorkflowScreen({root:node,core:{sale:()=>({...client,read:async()=>structuredClone(record)})},storage,actorId:'8'});await new Promise(resolve=>setImmediate(resolve));
  node.querySelector('[data-add-box]').events.click();
  const fill=(index,item,value)=>{const field=node.querySelectorAll('[data-box]').find(n=>n.dataset.box===String(index)&&n.dataset.item===item);field.value=value;field.events.input({target:field});};
  fill(0,'27',split?'1.000':'2.000');fill(0,'28','1.000');
  if(split){node.querySelector('[data-add-box]').events.click();fill(1,'27','1.000');}
  const before=[...store];await node.querySelector('[data-save-boxes]').events.click();
  assert.match(node.innerHTML,/FX2 için koli miktarı fişteki 1.000 ADET&#39;i aşıyor/);
  assert.equal(ids,0);assert.deepEqual(sent,[]);assert.deepEqual([...store],before);assert.equal(client.pending(),null);
  assert.equal(node.querySelector('[data-save-boxes]').disabled,false);assert.equal(screen.requestClose(),false);
  assert.equal(node.querySelectorAll('[data-box]').find(n=>n.dataset.box==='0'&&n.dataset.item==='27').value,split?'1.000':'2.000');
  fill(split?1:0,'27',split?'0.000':'1.000');await node.querySelector('[data-save-boxes]').events.click();
  assert.equal(ids,1);assert.equal(sent.length,1);assert.equal(sent[0].body.operation,'SAVE_CARTONS');assert.equal(sent[0].body.cartons.length,1);assert.equal(sent[0].body.cartons[0].items[0].quantityExact3,'1.000');assert.equal(client.pending().body.requestId,sent[0].body.requestId);screen.dispose();
 }
});
test('final cancellation requires explicit permission, reason and confirmation, then reads the same invoice',async()=>{
 for(const permitted of [false,true])for(const lost of [false,true]){
  const node=root(),writes=[];let pending=null,state='COMPLETED',reads=0;
  const record={invoiceId:'13',customerId:'2',customerName:'Ada',documentNo:'DS-13',documentDate:'2026-11-06',currency:'EUR',totalExact4:'1.1640',workflowState:state,version:'0x0000000000000013',items:[{itemId:'21',productId:'10',stockCode:'FX2',name:'Ürün',quantityExact3:'1.000',unitPriceExact4:'0.6000',lineTotalExact4:'0.6000'}],cartonItems:[]};
  const controller={pending:()=>pending,resolve:async()=>({state:'REVIEW_REQUIRED',resolution:'CANCELLATION_FENCE_REVIEW'}),read:async id=>{assert.equal(id,'13');reads++;return {...record,workflowState:state,cancellationReason:state==='CANCELLED'?'Fazla okutulan satış':null};},create:async(kind,body)=>{writes.push({kind,body});if(lost){pending={kind,body:{requestId:'7cbb7e06-ef75-4456-92e5-99f6d99b8312',...body}};return {state:'UNKNOWN'};}state='CANCELLED';return {state:'COMMITTED',invoiceId:'13',workflowState:state,replayed:false};}};
  const screen=mountDesktopWorkflowScreen({root:node,core:{sale:()=>controller,getUser:()=>({permissions:permitted?['sales.view','sales.cancel']:['sales.view','sales.edit','sales.finalize']})},storage:{getItem:key=>key.includes('.last.')?'13':null,setItem(){},removeItem(){}},actorId:'30002'});await new Promise(resolve=>setImmediate(resolve));
  if(!permitted){assert.equal(node.querySelector('[data-start-final-cancel]'),null);assert.equal(writes.length,0);screen.dispose();continue;}
  node.querySelector('[data-start-final-cancel]').events.click();assert.equal(writes.length,0);assert.equal(node.querySelector('[data-final-cancel]').disabled,true);node.querySelector('[data-final-cancel]').events.click();await new Promise(resolve=>setImmediate(resolve));assert.equal(writes.length,0);
  let input=node.querySelector('[data-final-cancel-reason]');input.value='  Fazla okutulan satış  ';input.events.input({target:input});assert.equal(node.querySelector('[data-final-cancel]').disabled,false);node.querySelector('[data-keep-final]').events.click();assert.equal(writes.length,0);assert.equal(node.querySelector('[data-final-cancel]'),null);
  node.querySelector('[data-start-final-cancel]').events.click();input=node.querySelector('[data-final-cancel-reason]');input.value='  Fazla okutulan satış  ';input.events.input({target:input});node.querySelector('[data-final-cancel]').events.click();await new Promise(resolve=>setImmediate(resolve));assert.deepEqual(writes,[{kind:'cancel',body:{invoiceId:'13',expectedVersion:'0x0000000000000013',reason:'Fazla okutulan satış'}}]);
  if(lost){assert.match(node.innerHTML,/sonucu henüz doğrulanamadı/);assert.equal(node.querySelector('[data-final-cancel]').disabled,true);node.querySelector('[data-final-cancel]').events.click();assert.equal(writes.length,1);assert.equal(reads,1);node.querySelector('[data-resolve]').events.click();await new Promise(resolve=>setImmediate(resolve));assert.match(node.innerHTML,/fiş koruyucu kilitte/);assert.match(node.innerHTML,/İstek korunuyor/);assert.equal(node.querySelector('[data-final-cancel]').disabled,true);assert.equal(writes.length,1);assert.equal(reads,1);}else{assert.match(node.innerHTML,/İptal gerekçesi: Fazla okutulan satış/);assert.equal(reads,2);assert.equal(node.querySelector('[data-start-final-cancel]'),null);}
  screen.dispose();
 }
});
for(const [workflowState,label] of [['DRAFT','Çıkışta cari hesaba yansıyacak'],['PREPARING','Çıkışta cari hesaba yansıyacak'],['READY','Çıkışta cari hesaba yansıyacak'],['CHECKED','Çıkışta cari hesaba yansıyacak'],['COMPLETED','Cari hesaba yansıyan'],['CANCELLED','İptal edilen fişin hesap tutarı']])test(`stored ${workflowState} document labels currency amount according to whether it is posted`,async()=>{
 const node=root(),record={invoiceId:'15',customerId:'2',customerName:'Ada',documentNo:'DS-15',documentDate:'2026-11-06',currency:'USD',currencySelection:{documentCurrency:'USD',accountId:'7',documentRateExact8:'40.00000000',accountRateExact8:'40.00000000',documentRateMode:'stored',accountRateMode:'stored'},accountCurrency:'USD',accountAmountExact4:'2.2500',amountTryExact4:'90.0000',totalExact4:'2.2500',workflowState,version:'0x0000000000000015',items:[{itemId:'25',productId:'10',stockCode:'P10',name:'Ürün10',quantityExact3:'2.000',unitPriceExact4:'0.7500',lineTotalExact4:'1.5000'},{itemId:'26',productId:'11',stockCode:'P11',name:'Ürün11',quantityExact3:'1.000',unitPriceExact4:'0.7500',lineTotalExact4:'0.7500'}],cartonItems:[]};
 const screen=mountDesktopWorkflowScreen({root:node,core:{sale:()=>({pending:()=>null,read:async()=>structuredClone(record)})},storage:{getItem:key=>key.includes('.last.')?'15':null,setItem(){},removeItem(){}},actorId:'8'});await new Promise(resolve=>setImmediate(resolve));assert(node.innerHTML.includes(label+': 2.2500 USD'));assert(node.innerHTML.includes('90.0000'));if(workflowState!=='COMPLETED')assert.doesNotMatch(node.innerHTML,/Cari hesaba yansıyan:/);screen.dispose();
});
function pricedPreview(input,preview){try{const items=desktopSeriesDraftItems({...input,preview}),lines=items.map((item,i)=>({...item,unitPriceExact4:preview.products[i].priceExact4,lineTotalExact4:(Number(item.quantityExact3)*Number(preview.products[i].priceExact4)).toFixed(4)})),total=lines.reduce((s,l)=>s+Number(l.lineTotalExact4),0).toFixed(4);return {...preview,quote:{lines,subtotalExact4:total,discountRateExact4:'0.0000',discountTotalExact4:'0.0000',totalExact4:total,maxDiscountRateExact4:'3.0000',writeSupported:true,belowCostWarning:false}};}catch{return preview;}}

async function barcodeFixture(){
 const node=root(),lookups=[],writes=[],previews=[];let pending=null,finish=null,late=false;const lookup=id=>({id,stockCode:'SKU'+id,productName:'Ürün'+id,unit:'ADET',currentStockExact3:'7.000',reservedExact3:'0.000',availableExact3:'7.000'}),controller={pending:()=>pending,preview:async input=>{previews.push(input);return pricedPreview(input,{revision:'a'.repeat(64),products:input.productIds.map(productId=>({productId,stockCode:'SKU'+productId,unit:'ADET',priceExact4:'12.0000',stockExact3:'7.000',reservedExact3:'0.000'}))});},create:async(...args)=>{writes.push(args);return {state:'UNKNOWN'};}};
 const core={sale:()=>controller,list:async kind=>({data:kind==='customers'?[{id:'2',customerCode:'C2',customerName:'Ada'}]:['10','11','12'].map(id=>({...lookup(id),seriesUnitId:id==='10'?'110':null,seriesFactorExact8:id==='10'?'6.00000000':null})),meta:{hasNextPage:false}}),productBarcode:async barcode=>{lookups.push(barcode);if(late)await new Promise(resolve=>{finish=resolve;});if(!['00092','00093','00094'].includes(barcode))throw Error('Barkodla eşleşen aktif ürün bulunamadı.');return lookup(barcode==='00092'?'10':barcode==='00093'?'11':'12');}};
 const screen=mountDesktopWorkflowScreen({root:node,core,storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8'});await new Promise(resolve=>setImmediate(resolve));node.querySelector('[data-customer]').events.change({target:{value:'2'}});
 return {node,screen,lookups,writes,previews,controller,setPending(){pending={kind:'draft'};},setLate(){late=true;},finish(){finish();},input(text){const field=node.querySelector('[data-product-barcode]');field.value=text;field.events.input({target:field});},add(){return node.querySelector('[data-add-barcode]').events.click();}};
}
test('two exact barcode products and another read of the first share one row per product, exact quantities and a fresh quote without writing',async()=>{
 const f=await barcodeFixture();for(const code of ['00092','00093']){f.input(code);await f.add();}f.input('00092');let prevented=false;f.node.querySelector('[data-product-barcode]').events.keydown({key:'Enter',preventDefault(){prevented=true;}});await new Promise(resolve=>setImmediate(resolve));assert.equal(prevented,true);assert.deepEqual(f.lookups,['00092','00093','00092']);assert.equal(f.node.querySelector('[data-product-barcode]').focused,true);assert.equal(f.node.querySelector('[data-quantity="0"]').value,'2.000');assert.equal(f.node.querySelector('[data-quantity="1"]').value,'1.000');assert.equal(f.node.querySelector('[data-product-barcode]').value,'');assert.equal(f.writes.length,0);await f.node.querySelector('[data-preview]').events.click();assert.deepEqual(f.previews[0].productIds,['10','11']);assert.deepEqual(f.previews[0].quantities,['2.000','1.000']);assert.match(f.node.innerHTML,/36.0000 TRY/);assert.equal(f.node.querySelector('[data-draft]').disabled,false);f.input('00093');await f.add();assert.equal(f.node.querySelector('[data-draft]'),null);assert.equal(f.node.querySelector('[data-quantity="1"]').value,'2.000');assert.equal(f.writes.length,0);f.screen.dispose();
});
test('third product, insufficient stock, malformed barcode and an unresolved write preserve the existing cart',async()=>{
 const f=await barcodeFixture();for(const code of ['00092','00093']){f.input(code);await f.add();}f.input('00094');await f.add();assert.match(f.node.innerHTML,/iki farklı ürün/);assert.equal(f.node.querySelector('[data-quantity="0"]').value,'1.000');const q=f.node.querySelector('[data-quantity="0"]');q.value='7';q.events.input({target:q});f.input('00092');await f.add();assert.match(f.node.innerHTML,/satılabilir stok/);assert.equal(f.node.querySelector('[data-quantity="0"]').value,'7');const count=f.lookups.length;f.input(' 00092');await f.add();assert.equal(f.lookups.length,count);f.setPending();f.input('00092');await f.add();assert.equal(f.lookups.length,count);assert.equal(f.writes.length,0);f.screen.dispose();
});
test('a scan never silently converts SERI quantities or applies a late reply after selection changes or disposal',async()=>{
 const f=await barcodeFixture();f.input('00092');await f.add();f.node.querySelector('[data-quantity-unit="0"]').events.change({target:{value:'SERİ',dataset:{quantityUnit:'0'}}});f.input('00092');await f.add();assert.match(f.node.innerHTML,/miktar birimini ADET seçin/);assert.equal(f.node.querySelector('[data-quantity="0"]').value,'1.000');f.screen.dispose();
 for(const dispose of [false,true]){const x=await barcodeFixture();x.setLate();x.input('00092');const work=x.add();if(dispose)x.screen.dispose();else{const quantity=x.node.querySelector('[data-quantity="0"]');quantity.value='5';quantity.events.input({target:quantity});}const html=x.node.innerHTML;x.finish();await work;if(dispose)assert.equal(x.node.innerHTML,html);else{assert.match(x.node.innerHTML,/Seçim değişti/);assert.equal(x.node.querySelector('[data-quantity="0"]').value,'5');assert.doesNotMatch(x.node.innerHTML,/value="10" selected/);}assert.equal(x.writes.length,0);x.screen.dispose();}
});
test('another tab creating a durable pending write during barcode lookup prevents a late local cart edit',async()=>{
 const f=await barcodeFixture();f.setLate();f.input('00092');const work=f.add();f.setPending();f.finish();await work;assert.match(f.node.innerHTML,/Önce son satış işlemini doğrulayın/);assert.equal(f.node.querySelector('[data-quantity="0"]').value,'1.000');assert.doesNotMatch(f.node.innerHTML,/value="10" selected/);assert.equal(f.writes.length,0);assert.equal(f.controller.pending().kind,'draft');f.screen.dispose();
});

