test('manager approval controls apply per-request five-percent, pending and expiry boundaries',async()=>{
 const node=root(),now=Date.now(),policy={version:1,actorId:'8',revision:'b'.repeat(64),canChangeSalePrice:false,maxDiscountRateExact4:'5.0000',canApproveUpToFive:true,canApproveAboveFive:false};let allowed=true,posts=0,listDenied=false;
 const base={actorId:'7',customerId:'2',documentDate:'2026-11-09',status:'PENDING',createdAt:now,expiresAt:now+600000,decision:null,invoice:null,quote:{currency:'TRY',lines:[],subtotalExact4:'10.0000',discountRateExact4:'5.0000',discountTotalExact4:'0.5000',totalExact4:'9.5000',belowCostWarning:false}};
 const rows=[{...base,id:'12',discountRateExact4:'4.9999'},{...base,id:'13',discountRateExact4:'5.0000'},{...base,id:'14',discountRateExact4:'5.0001'},{...base,id:'15',discountRateExact4:'5.0000',expiresAt:1},{...base,id:'16',discountRateExact4:'5.0000',status:'APPROVED'},{...base,id:'17',actorId:'8',discountRateExact4:'5.0000'}];
 const approvals={pending:()=>null,canApprove:rate=>allowed&&BigInt(rate.replace('.',''))<=50000n,list:async()=>{if(listDenied)throw Error('Onay listesine erişim reddedildi.');return {salesPolicy:policy,requests:rows};},approve:async()=>{posts++;return {state:'UNKNOWN'};}};
 const screen=mountDesktopWorkflowScreen({root:node,core:{sale:()=>({pending:()=>null}),salesApprovals:()=>approvals,list:async()=>({data:[],meta:{hasNextPage:false}})},storage:{getItem:()=>null,setItem(){},removeItem(){}},actorId:'8'}),tick=()=>new Promise(r=>setImmediate(r));
 await tick();node.querySelector('[data-approvals]').events.click();await tick();assert.deepEqual(node.querySelectorAll('[data-approval-approve]').map(x=>x.dataset.approvalApprove),['12','13']);
 const stale=node.querySelector('[data-approval-approve="13"]');allowed=false;stale.events.click();await tick();assert.equal(posts,0);assert.match(node.innerHTML,/Onay yetkiniz yok/);listDenied=true;node.querySelector('[data-approval-refresh]').events.click();await tick();assert.equal(node.querySelectorAll('[data-approval-approve]').length,0);assert.doesNotMatch(node.innerHTML,/İstek #12/);screen.dispose();
});


